// CDP driver: verify conflict "discard & reload latest" behavior
const DEBUG_PORT = 9223;
const APP = 'http://127.0.0.1:18080/';

async function getTarget() {
  for (let i = 0; i < 30; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${DEBUG_PORT}/json`)).json();
      const page = list.find(t => t.type === 'page' && t.url.startsWith(APP));
      if (page) return page;
    } catch {}
    await new Promise(r => setTimeout(r, 300));
  }
  throw new Error('no debug target');
}

let msgId = 0;
const pending = new Map();
let ws;
function send(method, params) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
async function evl(expression) {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error('page error: ' + JSON.stringify(r.exceptionDetails.exception?.description || r.exceptionDetails.text));
  return r.result.value;
}
async function waitFor(expr, label, timeout = 5000) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeout) {
    if (await evl(expr)) return;
    await new Promise(r => setTimeout(r, 100));
  }
  throw new Error('timeout waiting: ' + label);
}
function assert(cond, label) {
  if (!cond) { console.error('FAIL: ' + label); process.exitCode = 1; }
  else console.log('ok: ' + label);
}

const target = await getTarget();
ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id).resolve(m.result); pending.delete(m.id); }
};
await send('Runtime.enable', {});

// 1. open the draft for editing (currently version 3, "B的第二次保存")
await evl(`[...document.querySelectorAll('#article-list button')].find(b=>b.textContent==='编辑').click()`);
await waitFor(`!document.getElementById('edit-banner').hidden`, 'edit mode entered');
assert(await evl(`document.getElementById('title').value`) === 'B的第二次保存', 'edit opened with v3 title');

// 2. type own changes and save -> 409 conflict
await evl(`document.getElementById('title').value='A的输入'; document.getElementById('summary').value='A的摘要';`);
await evl(`document.getElementById('save-btn').click()`);
await waitFor(`!document.getElementById('conflict-box').hidden`, 'conflict box shown');
assert(await evl(`document.getElementById('title').value`) === 'A的输入', 'conflict keeps own input');
assert(await evl(`document.getElementById('conflict-box').textContent.includes('B的第二次保存')`), 'conflict shows saved v3');

// 3. the other page saves AGAIN (v3 -> v4); first conflict comparison is now stale
await evl(`fetch('/api/articles/' + ${JSON.stringify('__ID__')}, {method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({title:'B的第三次保存',summary:'s4',body:'b4 第二段\\n\\n<html>保留</html>',version:3})}).then(r=>r.json())`)
  .then(r => assert(r.article && r.article.version === 4, 'other page saved v4'));

// 4. dirty-during-read: click discard, then modify a field before the read finishes; choose keep
await evl(`window.__confirmAnswer=false; window.__confirmMsgs=[]; window.confirm=(m)=>{window.__confirmMsgs.push(m); return window.__confirmAnswer};`);
await evl(`
  const btn=[...document.querySelectorAll('#conflict-box button')].find(b=>b.textContent.includes('放弃当前输入'));
  btn.click();
  document.getElementById('title').value='等待期间的修改';
  'clicked';
`);
await waitFor(`!document.getElementById('save-btn').disabled`, 'read settled (keep path)');
assert(await evl(`window.__confirmMsgs.length`) === 1, 'confirm asked for dirty-during-read');
assert(await evl(`document.getElementById('title').value`) === '等待期间的修改', 'keep: current input preserved');
assert(await evl(`document.getElementById('edit-banner').textContent.includes('B的第二次保存')`), 'keep: original edit target/baseline unchanged');
assert(await evl(`!document.getElementById('conflict-box').hidden`), 'keep: conflict box still available');
assert(await evl(`![...document.querySelectorAll('#conflict-box button')].some(b=>b.disabled)`), 'keep: conflict buttons re-enabled');

// 5. restore the field to its read-start value, click discard again -> no confirm needed, loads v4
await evl(`document.getElementById('title').value='A的输入';`);
await evl(`[...document.querySelectorAll('#conflict-box button')].find(b=>b.textContent.includes('放弃当前输入')).click()`);
await waitFor(`document.getElementById('title').value==='B的第三次保存'`, 'latest v4 loaded');
assert(await evl(`window.__confirmMsgs.length`) === 1, 'restored-to-snapshot value: no second confirm');
assert(await evl(`document.getElementById('summary').value`) === 's4', 'loaded latest summary');
assert(await evl(`document.getElementById('body').value`) === 'b4 第二段\n\n<html>保留</html>', 'loaded latest body (multiline + html-like text)');
assert(await evl(`document.getElementById('edit-banner').textContent.includes('B的第三次保存')`), 'banner shows latest title');
assert(await evl(`document.getElementById('edit-banner').textContent.includes(${'JSON'}))` === false || true, 'banner placeholder');
assert(await evl(`document.getElementById('edit-banner').textContent.includes('__ID__')`), 'banner shows article id');
assert(await evl(`document.getElementById('edit-banner').textContent.includes('创建时间')`), 'banner shows created time');
assert(await evl(`document.getElementById('conflict-box').hidden`), 'conflict box hidden after load');
const listText = await evl(`document.getElementById('article-list').textContent`);
assert(listText.includes('B的第三次保存') && listText.includes('s4'), 'list title/summary match loaded version');
assert(await evl(`document.querySelector('#article-list .editing-tag')?.textContent`) === '编辑中', 'list shows 编辑中 tag');

// 6. save again with no changes: must use freshly loaded version 4 -> 200, no conflict
await evl(`document.getElementById('save-btn').click()`);
await waitFor(`document.getElementById('status').textContent.includes('修改已保存')`, 'save after reload succeeds');
assert(await evl(`document.getElementById('conflict-box').hidden`), 'no false conflict after reload');
const after = await evl(`fetch('/api/articles/__ID__').then(r=>r.json())`);
assert(after.article.version === 5, 'save based on freshly loaded version (now v5)');

// 7. failure path: other page saves v5->v6, we conflict again, then the draft disappears
await evl(`fetch('/api/articles/__ID__',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({title:'B的第四次保存',summary:'s6',body:'b6',version:5})}).then(r=>r.json())`);
await evl(`document.getElementById('title').value='A的第二轮输入'; document.getElementById('save-btn').click()`);
await waitFor(`!document.getElementById('conflict-box').hidden`, 'second conflict shown');
console.log('READY_FOR_DELETE');
process.stdout.write('');

